import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Totals-and-Subtotals.md","filePath":"manual-en/CTABLES-Totals-and-Subtotals.md","lastUpdated":1785684581000}'),r={name:"manual-en/CTABLES-Totals-and-Subtotals.md"};function l(s,t,n,i,c,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h4 id="_15-7-5-3-totals-and-subtotals" tabindex="-1">15.7.5.3 Totals and Subtotals <a class="header-anchor" href="#_15-7-5-3-totals-and-subtotals" aria-label="Permalink to &quot;15.7.5.3 Totals and Subtotals&quot;">​</a></h4><p><code>CATEGORIES</code> also controls display of totals and subtotals. By default, or with <code>TOTAL=NO</code>, totals are not displayed. Use <code>TOTAL=YES</code> to display a total. By default, the total is labeled “Total”; use <code>LABEL=&quot;_label_ &quot;</code> to override it.</p><p>Subtotals are also not displayed by default. To add one or more subtotals, use an explicit category list and insert <code>SUBTOTAL</code> or <code>HSUBTOTAL</code> in the position or positions where the subtotal should appear. The subtotal becomes an extra row or column or layer. <code>HSUBTOTAL</code> additionally hides the categories that make up the subtotal. Either way, the default label is “Subtotal”, use <code>SUBTOTAL=&quot;_label_ &quot;</code> or <code>HSUBTOTAL=&quot;_label_ &quot;</code> to specify a custom label.</p><p>The following example syntax and output show how to use <code>TOTAL=YES</code> and <code>SUBTOTAL</code>:</p><pre><code>CTABLES
    /TABLE freqOfDriving
    /CATEGORIES VARIABLES=freqOfDriving [OTHERNM, SUBTOTAL=&#39;Valid Total&#39;,
                                         MISSING, SUBTOTAL=&#39;Missing Total&#39;]
                                        TOTAL=YES LABEL=&#39;Overall Total&#39;.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td>Valid Total</td><td>6972</td><td></td></tr><tr><td>Don&#39;t know</td><td>8</td><td></td></tr><tr><td>Refused</td><td>19</td><td></td></tr><tr><td>Missing Total</td><td>27</td><td></td></tr><tr><td>Overall Total</td><td>6999</td><td></td></tr></tbody></table><p>By default, or with <code>POSITION=AFTER</code>, totals are displayed in the output after the last category and subtotals apply to categories that precede them. With <code>POSITION=BEFORE</code>, totals come before the first category and subtotals apply to categories that follow them.</p><p>Only categorical variables may have totals and subtotals. Scalar variables may be “totaled” indirectly by enabling totals and subtotals on a categorical variable within which the scalar variable is summarized. For example, the following syntax produces a mean, count, and valid count across all data by adding a total on the categorical <code>region</code> variable, as shown:</p><pre><code>CTABLES /TABLE=region &gt; monthDaysMin1drink [MEAN, VALIDN]
    /CATEGORIES VARIABLES=region TOTAL=YES LABEL=&#39;All regions&#39;.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Mean</th><th>Count</th><th>Valid N</th></tr></thead><tbody><tr><td>20. On how many of the thirty days in this typical month did you have one or more alcoholic beverages to drink?</td><td>Region</td><td>NE</td><td>5.6</td><td>1409</td><td>945</td></tr><tr><td>MW</td><td>5.0</td><td>1654</td><td>1026</td><td></td><td></td></tr><tr><td>S</td><td>6.0</td><td>2390</td><td>1285</td><td></td><td></td></tr><tr><td>W</td><td>6.5</td><td>1546</td><td>953</td><td></td><td></td></tr><tr><td>All regions</td><td>5.8</td><td>6999</td><td>4209</td><td></td><td></td></tr></tbody></table><p>By default, PSPP uses the same summary functions for totals and subtotals as other categories. To summarize totals and subtotals differently, specify the summary functions for totals and subtotals after the ordinary summary functions inside a nested set of <code>[]</code> following <code>TOTALS</code>. For example, the following syntax displays <code>COUNT</code> for individual categories and totals and <code>VALIDN</code> for totals, as shown:</p><pre><code>CTABLES
    /TABLE isLicensedDriver [COUNT, TOTALS[COUNT, VALIDN]]
    /CATEGORIES VARIABLES=isLicensedDriver TOTAL=YES MISSING=INCLUDE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th><th>Valid N</th></tr></thead><tbody><tr><td>D7a. Are you a licensed driver; that is, do you have a valid driver&#39;s license?</td><td>Yes</td><td>6379</td><td></td></tr><tr><td>No</td><td>572</td><td></td><td></td></tr><tr><td>Don&#39;t know</td><td>4</td><td></td><td></td></tr><tr><td>Refused</td><td>44</td><td></td><td></td></tr><tr><td>Total</td><td>6999</td><td>6951</td><td></td></tr></tbody></table>`,13)])])}const b=d(r,[["render",l]]);export{T as __pageData,b as default};
